/// Dart source for the committed stub map.
///
/// Shared by the generator and the drift test.
String generatedDart(Map<String, String> stubs) =>
    '// Generated by tool/generate_bindings.dart. Do not edit.\n'
    '// ignore_for_file: lines_longer_than_80_chars, '
    'leading_newlines_in_multiline_strings, unnecessary_raw_strings\n'
    'const generatedBindingStubs = <String, String>{\n'
    '${stubs.entries.map((e) => "  '${e.key}': r'''${e.value}''',\n").join()}'
    '};\n';
